window.__finlexDocLoaded(10008,{"id":10008,"articles":[{"id":1000008,"no":"Decision Summary","heading":"Lease Term & Enforceability Judgements (IFRS 16.18–21 & B34–B40)","text":"[Recurring Enforcement Findings]\n• Broader economics (IFRS 16.B34): aligned with the IFRIC Agenda Decision on lease term, entities must consider broader economic penalties (e.g., unamortised leasehold improvements, relocation costs)—not just contractual termination penalties—when determining enforceable period.\n• Disclosure of future cash outflows not reflected in lease liabilities (IFRS 16.59(b)): material extension options excluded from the lease term require transparent quantitative disclosure.\n\nOfficial ESMA EECS Decisions Index: https://www.esma.europa.eu/document/list-decisions-published-extracts-eecss-database-enforcement","seq":0}]});
